import{_ as r,a0 as o,w as a,s as d,I as n,x as u,a1 as i,A as p,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"精簡版 Xubuntu：建立你自己的發行版的機會 | LCTT x X-CMD","titleTemplate":false,"description":"精簡版 Xubuntu：建立你自己的發行版的機會 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精簡版 Xubuntu：建立你自己的發行版的機會 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精簡版 Xubuntu：建立你自己的發行版的機會 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230306.0 ⭐️ Xubuntu Minimal Opportunity to Build Your Own Distro","title":"精簡版 Xubuntu：建立你自己的發行版的機會","tag":"202303","desc":""},"relativePath":"202303/20230306.0 ⭐️ Xubuntu Minimal Opportunity to Build Your Own Distro.md","filePath":"[post].md"}'),b={name:"202303/20230306.0 ⭐️ Xubuntu Minimal Opportunity to Build Your Own Distro.md"};function e(m,t,f,w,x,X){const l=o("Link");return a(),d("div",null,[t[26]||(t[26]=n("h1",{id:"精簡版-xubuntu-建立你自己的發行版的機會",tabindex:"-1"},[u("精簡版 Xubuntu：建立你自己的發行版的機會 "),n("a",{class:"header-anchor",href:"#精簡版-xubuntu-建立你自己的發行版的機會","aria-label":"Permalink to “精簡版 Xubuntu：建立你自己的發行版的機會”"},"​")],-1)),t[27]||(t[27]=n("blockquote",null,[n("p",null,"Xubuntu 團隊從 23.04 版本開始推出了一個包含少量組件的精簡 ISO。以下是它的情況。")],-1)),t[28]||(t[28]=n("p",null,[n("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/03/xubuntu1.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=u("幾天前，Canonical ",-1)),i(l,{href:"https://linux.cn/article-15588-1.html"},{default:p(()=>[...t[0]||(t[0]=[u("宣佈",-1)])]),_:1}),t[2]||(t[2]=u("，Ubuntu 23.04 “Lunar Lobster” 版本官方的精簡 ISO 安裝文件正在製作中。雖然截至發稿時，該鏡像還沒有出現，但 Xubuntu 團隊設法推出了他們自己的精簡 ISO 安裝鏡像。",-1))]),t[29]||(t[29]=s('<p>Xubuntu 被數百萬人使用，並且一直是許多其他發行版的基礎。對於一些用户來説，默認安裝可能帶有太多的預裝包和功能，導致系統臃腫，計算機性能降低。這就是 Xubuntu 精簡安裝發揮作用的地方。在這篇文章中，我們將採取實踐的方式來安裝和探索精簡版 Ubuntu 的功能。</p><p>讓我們看看你在 Xubuntu 精簡安裝中得到了什麼，以及與普通桌面安裝程序的比較。</p><h3 id="xubuntu-精簡安裝" tabindex="-1">Xubuntu 精簡安裝 <a class="header-anchor" href="#xubuntu-精簡安裝" aria-label="Permalink to “Xubuntu 精簡安裝”">​</a></h3><p>第一個明顯的區別是精簡安裝與標準桌面安裝程序的 ISO 鏡像大小。它的大小大約減少了 39%。</p><div class="table-wrap"><table><thead><tr><th></th><th>精簡版</th><th>標準版</th></tr></thead><tbody><tr><td>桌面安裝程序（ISO）大小</td><td>1.7 GB</td><td>2.8 GB</td></tr></tbody></table></div><p>在使用精簡版安裝程序安裝 Xubuntu 時，你不會在 Ubiquity 中看到“<ruby>精簡安裝<rt>minimal install</rt></ruby>”的選項。其餘的安裝步驟都是一樣的，沒有區別。</p><p>然而，主要的區別是在安裝的系統上。最小安裝只需要 7.2GB 的磁盤空間，而同一版本的標準安裝則需要 11GB。</p><div class="table-wrap"><table><thead><tr><th></th><th>精簡版</th><th>標準版</th></tr></thead><tbody><tr><td>磁盤使用空間</td><td>7.2 GB</td><td>11 GB</td></tr></tbody></table></div><p>因為許多應用程序被剝離了。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/03/Xubuntu-minimal-and-standard-install-comparison.jpg" alt="Xubuntu 精簡和標準安裝比較"></p><p>在 Xubuntu 的精簡安裝中，你會得到以下東西：</p><ul><li>終端</li><li>文件管理器</li><li>所有的設置應用</li><li>Synaptic 包管理器</li><li>屏幕截圖應用</li></ul><p>就這些了。</p><p>如果你把它與標準版相比，你就不會有以下的應用：</p><ul><li>Firefox 瀏覽器</li><li>Thunderbird 郵件客户端</li><li>媒體播放器（音頻和視頻）</li><li>LibreOffice 套件</li><li>Transmission Torrent 客户端</li><li>GNOME 軟件</li><li>遊戲</li><li>Gigolo 遠程連接客户端</li><li>磁盤使用工具</li></ul><h3 id="精簡版-xubuntu-上的-snap-包" tabindex="-1">精簡版 Xubuntu 上的 Snap 包 <a class="header-anchor" href="#精簡版-xubuntu-上的-snap-包" aria-label="Permalink to “精簡版 Xubuntu 上的 Snap 包”">​</a></h3><p>令我驚訝的是，精簡版 Xubuntu 沒有安裝 Snap！甚至連 Snap 守護程序都沒有。而且也沒有 Flatpak。</p><p>所以，實際上你得到的是一個沒有 Snap 的 Xubuntu 系統，但有一個核心的 Ubuntu 基礎。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/03/Look-no-snap.jpg" alt="看，沒有 Snap"></p><p>但我不確定主 Ubuntu 的精簡 ISO 會有同樣的情況。我想我們需要等待和觀察。</p><h3 id="接下來是什麼" tabindex="-1">接下來是什麼？ <a class="header-anchor" href="#接下來是什麼" aria-label="Permalink to “接下來是什麼？”">​</a></h3><p>所以，現在你有了一個初級的 Xubuntu 桌面。使用 Synaptic 包管理器，你可以開始構建和安裝你喜歡的應用。</p>',22)),n("p",null,[t[4]||(t[4]=u("例如，你可以 ",-1)),i(l,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:p(()=>[...t[3]||(t[3]=[u("設置 Flatpak",-1)])]),_:1}),t[5]||(t[5]=u(" 並從一個基本的瀏覽器、媒體播放器、LibreOffice 等開始。",-1))]),t[30]||(t[30]=n("p",null,"如果你是一個開發者，你可以安裝 Visual Studio Code 或一些 IDE。",-1)),t[31]||(t[31]=n("p",null,"以這個版本為基礎，你可以為你的工作流程建立任何發行版。",-1)),t[32]||(t[32]=n("h3",{id:"總結",tabindex:"-1"},[u("總結 "),n("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[33]||(t[33]=n("p",null,"Xubuntu 精簡安裝對於那些想要完全控制他們系統上安裝的東西，並且喜歡更快、更有效的基於 Ubuntu 的發行版的用户來説是一個很好的選擇。",-1)),t[34]||(t[34]=n("p",null,"Xfce 的可定製性、輕量級特性和使用 synaptic 的包管理使它成為任何定製構建的理想選擇。",-1)),n("p",null,[t[7]||(t[7]=u("你可以從這個 ",-1)),i(l,{href:"https://cdimage.ubuntu.com/xubuntu/daily-live/current/"},{default:p(()=>[...t[6]||(t[6]=[u("頁面",-1)])]),_:1}),t[8]||(t[8]=u(" 下載精簡版 ISO。記住，它還沒有正式發佈，而且是一個日常構建的副本。所以使用它要",-1)),t[9]||(t[9]=n("strong",null,"謹慎",-1)),t[10]||(t[10]=u("。",-1))]),t[35]||(t[35]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=u("via: ",-1)),i(l,{href:"https://www.debugpoint.com/xubuntu-minimal/"},{default:p(()=>[...t[11]||(t[11]=[u("https://www.debugpoint.com/xubuntu-minimal/",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=u("作者：",-1)),i(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...t[13]||(t[13]=[u("Arindam",-1)])]),_:1}),t[18]||(t[18]=u(" 選題：",-1)),i(l,{href:"https://github.com/lkxed/"},{default:p(()=>[...t[14]||(t[14]=[u("lkxed",-1)])]),_:1}),t[19]||(t[19]=u(" 譯者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:p(()=>[...t[15]||(t[15]=[u("geekpi",-1)])]),_:1}),t[20]||(t[20]=u(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[16]||(t[16]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=u("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[21]||(t[21]=[u("LCTT",-1)])]),_:1}),t[24]||(t[24]=u(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:p(()=>[...t[22]||(t[22]=[u("Linux中國",-1)])]),_:1}),t[25]||(t[25]=u(" 榮譽推出",-1))])])}const O=r(b,[["render",e]]);export{S as __pageData,O as default};
